(() => {
  const C = window.CURTAIN_CONTENT;
  const extend = (id, parts) => {
    const a = C.articles.find(x => x.id === id);
    if (!a) return;
    for (const [heading, ...paragraphs] of parts) a.chapters.push({heading, paragraphs});
    a.paragraphs = a.chapters.flatMap(c => c.paragraphs);
  };
  const add = (id, section, title, subtitle, lead, source, parts) => {
    const chapters = parts.map(([heading, ...paragraphs]) => ({heading, paragraphs}));
    C.articles.push({id, section, title, subtitle, lead, source, eyebrow: '文明研究 / 馆藏专题', chapters, paragraphs: chapters.flatMap(c => c.paragraphs)});
  };
  extend('camoria', [
    ['中央大陆与普诺伊瓦', '卡莫瑞亚位于五大陆中央，四周有海域环绕，气候相对温和而略显干燥。来自英国的巫师及其后裔在此留下了深刻的文化影响。大陆中央的普诺伊瓦不仅是一座大都会，也是魔法联合部总部所在地。', '联合部在卡莫瑞亚直接行使最高行政权。城市管理由其官僚体系承担，地方行政长官通常由中央任命。公共机构因而不只是远方的裁决者，它也直接参与城市的日常治理。', '政治中心的地位并不意味着所有居民拥有相同的权力。既有资料显示，本地人与贵族或亲贵族家族在进入行政体系时较易获得机会；其他大陆的人才也可能进入，但比例相对较小。'],
    ['矿石和填充工坊', '卡莫瑞亚本身也出产蕴法石，产量在五大陆中居第二位。然而，中央大陆最突出的经济优势不是单纯的开采数量，而是高级巫师的集中。', '蕴法石从矿物成为可用的施法媒介，需要施法者将咒语填入。高级施法者、政治机构与既有家族资源的集中，使卡莫瑞亚在这一环节拥有比矿产份额更大的影响。', '这也解释了它与埃斯佩兰萨之间的互相依赖：一方拥有最丰富的原料产量，另一方在高水平填充方面具有优势。资源的价值并不只由矿山的位置决定。'],
    ['秩序与自我形象', '支配、预言、知识与神圣魔法在卡莫瑞亚的研究中具有代表性。地方文化中对精确、理性和秩序的重视，与中央政治机构的存在共同构成了其对外形象。', '不过，一片大陆的自我描述不等于每位居民的生活。研究者需要把公共政治语言、家族传统与不同城市居民的经验分别考察。']
  ]);
  extend('eisen', [
    ['气候、街区与时间', '艾森洛德位于西北，气候偏寒冷干燥。来自德国与瑞士地区的巫师传统，在当地社会形成过程中留下重要影响。城市街区常以规整方式排列，钟楼的报时也与居民对时间的重视联系在一起。', '地方文化中对纪律与守约的推崇，并不能说明所有居民都遵循同一生活方式，但它确实是一条理解工坊、军队与公共生活的线索。'],
    ['制造比开采更重要', '相比蕴法石资源丰富的大陆，艾森洛德矿脉较少。它的重要优势来自精密操作、结界与造物制造的长期积累。', '从日常器具、农用机关到防护器具，不同造物都需要制造、测试和维护。工坊生产的不只是一次性的魔法效果，还包括在反复使用中保持稳定的器具。', '当器物进入其他大陆的市场，制造地与使用地之间还需要形成关于品质、维护及契约的共同理解。艾森洛德的工艺声誉，与这种长期的信任关系密切相关。'],
    ['防御与协作', '结界、防护、大地与精密操作是地方魔法传统中的重要方向。当地军队也以群体共同施法见长；这种实践要求参与者协调自己的动作和魔力，而不仅依靠个人施法能力。']
  ]);
  extend('northlands', [
    ['寒冬与生存', '茨威尔格诺位于东北，严寒与积雪深刻影响当地生活。被称为“茨威尔之冬”的漫长寒季持续三个季节，住房、交通与物资准备都需要考虑这一环境。', '冰霜与强化魔法是当地的重要传统，追猎、极光及大型石像操纵等体系也在现存资料中有所记载。身体训练与近身作战是部分地方实践的显著特点，但并不足以概括所有居民的生活。'],
    ['冰原矿脉与皮毛', '北方大陆的蕴法石产量居五大陆第三位。矿脉位于冰原与冻土之下，开采不仅是寻找矿石，也要应对寒冷条件与运输距离。', '神奇生物的皮毛及相关制品是另一项重要产业。适应寒冷环境的生物提供了厚实耐用的材料，这些材料经过加工后，还会被运往较温暖的大陆。', '当地也保存着古老的炼金传统。不同群体对技术与知识的传承方式并不完全一致，地方研究不宜将这些实践简单归入单一、统一的体系。']
  ]);
  extend('esperanza', [
    ['港口与水产', '埃斯佩兰萨位于西南，气候炎热而湿润。大陆东南部的群岛拥有贸易港口和丰富水产：远洋商船与归航渔船共同使用港口，但它们连接的是不同尺度的经济活动。', '港口也是饮食、音乐、人员与消息流动的地方。节奏、舞蹈、心灵、阳光、火焰和海洋魔法，都是与当地有关的研究传统；不同的实践并不必然服务于相同的职业或社会阶层。'],
    ['从矿山到填充', '埃斯佩兰萨拥有五大陆最丰富的蕴法石矿脉，是重要的原料供应地。原石离开矿山之后，还需要经过填充与运输，才可能成为工坊、机关或其他场所使用的资源。', '高水平咒语填充与高级施法者的分布密切相关。卡莫瑞亚在这一环节具有优势，因此，开采最丰富的地区并不自动控制生产链上的每一个步骤。', '对经济史而言，原料输出、施法者训练与最终使用之间的关系，提供了观察两片大陆合作与利益差异的线索。'],
    ['食物与地方名声', '埃斯佩兰萨的饮食在帷幕世界享有较高声誉。资料中提到，普诺伊瓦一间知名烤肉店由来自该大陆的人经营。这样的跨地域经营，使饮食也成为地方文化被外界认识的途径。']
  ]);
  extend('enchantevis', [
    ['森林与尚未记录的地方', '昂尚特维斯位于东南，气候温和而略湿润。大陆腹地有广阔森林，其中存在难以辨识的生物和尚未充分调查的区域。', '森林并非只有一种意义：对采集者而言，它提供草药和魔药原料；对研究者而言，它包含需要长期辨认的生长环境；对其他居民而言，它也可能是原本的生活空间。'],
    ['药材与魔药', '当地拥有丰富的草药及珍稀魔药原料，其中一部分通过贸易进入其他大陆。资源的价值不仅来自发现植物，也依赖辨识、采集、保存和后续调配的知识。', '与矿石或造物相比，药材的供应更直接地依赖生长环境。森林资源和地方专业知识共同构成了昂尚特维斯在跨大陆经济中的位置。'],
    ['文学与魔法研究', '幻象、梦境、镜子、星辰与森林魔法，是现存资料中与这片大陆相联系的研究方向。昂尚特文学则以情绪、欲望和人物之间难以言说的关系为重要表现内容，在大陆之外也拥有读者。', '研究作品时，应区分文学传统所偏爱的主题和所有居民的真实生活。作品能够表现情感与想象，却不能代替对社会各阶层的调查。']
  ]);
  add('treaty-study', 'history', '和平条约的两种约束', '从战争联盟到血脉誓约', '一份和平协议可以在政治秩序消失之后，仍然继续约束它的一方。', ['和平条约', '离散纪'], [
    ['联盟与谈判', '公元五世纪前后，巫师曾与亚瑟王的联盟共同参与战争。战争结束时，双方需要面对一个新的问题：战场上相互依赖的力量，能否在和平时期形成持久的共同秩序？', '巫师首领与亚瑟王达成和平条约，确立人类与巫师和平共处、互不侵犯的原则。现存记载认为，条约中有一项特殊安排：巫师首领将约束与巫师血脉相结合。'],
    ['不对称的承诺', '这一誓约对巫师具有持续的魔法约束力，而人类一方并未受到同等的超自然限制。人类对条约的履行，需要依靠政权、制度与社会对承诺的维系。', '从当时的政治处境看，这可以被理解为巫师对和平作出的强烈保证；从制度结构看，它也造成了不同的责任。无论签署者是否预见后果，两种约束对政治变化的反应并不相同。'],
    ['王权消失之后', '亚瑟时代的政治联盟逐渐解体，领土与统治者在战争、继承中多次变化。原先见证盟约的人和机构不再存在，后世人类社会对条约的记忆也逐渐淡去。', '血脉誓约却不以某个后继政权承认条约为前提。对巫师而言，古老协议仍然是实际存在的限制；对许多普通人而言，与巫师缔约的时代则越来越接近传说。'],
    ['从分歧到迁徙', '在社会敌意增长的时期，誓约对组织大规模攻击性反制形成障碍。这并不意味着每位施法者都完全失去逃避和有限自保的能力；问题在于能够采取何种集体行动。', '在十四至十五世纪的漫长变化中，一部分巫师最终选择迁往帷幕。条约不是解释迁徙的唯一原因，但它是理解双方政治处境为何不对等的重要条件。']
  ]);
  add('ministry-government', 'history', '魔法联合部如何治理', '中央行政、地方分部与均势', '在一个跨越五大陆的政治空间中，公共权威必须同时面对距离、地方政府与不同势力。', ['魔法联合部', '界门', '货币'], [
    ['同一机构的两种位置', '魔法联合部总部位于卡莫瑞亚的普诺伊瓦。它在卡莫瑞亚直接承担最高行政职责，同时对其他大陆的国家拥有监管、约束和介入权力。', '这两种地位不能混为一谈：直接管理城市，与监督其他地方政府，并不是完全相同的政治关系。各大陆分部负责与当地政府日常联络，再向总部传递信息。'],
    ['日常工作的条件', '分部与总部之间可使用灵界传信，也可通过界门传送人员。通信与交通条件影响机构如何协调事务；但界门分布有限，日常管理不可能仅靠少数大型设施完成。', '登记、造物监管、法律执行和通用货币发行，都需要持续的职业官僚工作。一个政治机构的影响，不仅表现在重大危机时的决定，也体现在平时反复处理的事务中。'],
    ['权力均衡与介入', '联合部的重要原则是维持政治力量的平衡。地方冲突不一定引发立即介入；当某个政权可能整合整片大陆的资源、进而威胁既有均势时，联合部则可能采取强硬行动。', '这种判断并没有一条简单、明确的固定边界。行动的必要性、规模与潜在反弹，都需要在具体局势中衡量；最高理事会通过投票作出相关决定。'],
    ['公共权威与既有家族', '联合部由数个贵族家族的领导者共同创立。机构在发展中形成了自身的官僚与执行体系，但家族资源、职业官僚、宗教势力与地方强者仍然可能影响政治。', '现有资料尚不足以完整重建其内部派系或最高理事会的全部席位安排。对外公开的决定，不应被误认为完整反映了内部讨论过程。']
  ]);
  add('inhabitants-history', 'geography', '帷幕中的原住民与迁徙者', '回路、技术传统与相遇之后', '在欧洲巫师迁入以前，五大陆已有人居住，迁徙改变的是不同群体之间的关系。', ['种族', '帷幕起源', '炼金术'], [
    ['先于大迁徙的居民', '五大陆早在帷幕形成和欧洲巫师大迁徙之前就已存在。现存资料将多种不同的居民统称为亚人或亚种，其中包括翼人、质人族和生活于水中的群体。', '“亚人”是范围很广的名称，不是单一语言、文化或政治组织。研究迁徙史时，将所有原住民看作同一个整体，会掩盖他们各自不同的生活。'],
    ['回路与魔法实践', '巫师的魔法回路具有较强的可塑性；部分亚人群体的回路结构较固定，并与特定魔法实践有天然亲和。这种差异影响了学习和施法的方式。', '对亚人的描述不能直接推导每个个体的能力或地位。不同种群拥有不同的身体条件、知识传统和生活环境，而公共分类本身也可能带有观察者的立场。'],
    ['迁徙与知识交流', '大迁徙带来了新的施法传统和社会关系。土地、聚居与资源引发的紧张，并未阻止所有交流，但也使接触无法被概括为一段完全和平的融合史。', '炼金术提供了一个例子：巫师与质人族的传统有共同源流，之后在分类、术语和操作上逐渐分化。即便两种方法产生类似结果，使用者也未必能轻易理解彼此的过程。'],
    ['共同生活仍有差异', '随着公共机构发展，不同群体逐渐形成较为稳定的共处关系；历史上的紧张和社会差异却不会因制度建立而立刻消失。讨论共同社会，需要把合作与不平等同时纳入视野。']
  ]);
  add('noble-house-records', 'history', '古老家族与地方社会', '产业、传承与家族影响力', '十九贵族并非整齐一致的政治共同体。家族掌握的技术与资源，也不局限于土地和头衔。', ['十九贵族', '十九家', '五大陆概览'], [
    ['名称与变化', '十九贵族是后世沿用的历史称谓，指向一批在帷幕世界长期具有影响的巫师家族。家族之间既有合作，也存在竞争；它们的权力、财富与社会声望并不会始终保持一致。', '“上三族”是克罗蒂、摩伊拉和德维雷斯的合称。这个称谓记录了特殊的历史地位，并不证明三家在每一时期都拥有共同立场或组成正式联盟。'],
    ['支配、预言与裁决', '克罗蒂家族的传统与支配操控魔法联系密切。家族所掌握的知识与经济资源，使其成为研究古老巫师家族如何维持影响的重要对象。', '摩伊拉的家族历史与命运和预言等问题相关。关于其早期活动，现存公开材料并不总是完整；研究者需要区分可确认的世系、后世解释以及尚有争议的推测。', '德维雷斯则与司法、审判和裁决体系联系密切。能够鉴定契约与裁决争端的权威，既可能帮助政治对手达成协议，也使裁决者在公共生活中拥有重要力量。'],
    ['家族与产业', '不同家族参与的活动各有侧重。艾森洛德的艾泽勒家族与造物制造及精密操作传统相关；茨威尔格诺的索科洛夫家族涉及神奇生物皮毛及其制品；埃斯佩兰萨的伊格尼斯家族则与火焰魔法有关。', '卡莫瑞亚的诺斯塔格尔家族与心灵疗养机构有关，西德拉家族的传统则涉及占卜预言和星辰魔法。这些联系能帮助读者理解家族如何进入专业活动，但不应被当成对每一位成员的完整描述。'],
    ['名单的边界', '现有名录并未完整保存每一家族的名称、产业和代表人物。一些记录只留下居住地或魔法体系，另一些条目则仍有空缺。', '对历史研究而言，空缺本身就是资料的一部分。不能为了凑齐十九个名字而把未知内容补成未经证实的事实；也不能只依据某个家族现居地，推断它从未在其他地区活动。']
  ]);
  add('world-trade', 'geography', '帷幕边界上的贸易', '物资如何跨越两种经济', '帷幕限制了普通人对五大陆的感知，却没有使所有物资与信息的流动彻底停止。', ['货币', '帷幕起源', '界门'], [
    ['两种货币之间', '帷幕世界的索比恩与人类世界的人民币之间，没有公开的兑换体系，也不存在固定汇率。两边的经济结构和可供交换的资源不同，不能简单地把某种魔法材料折算成一项稳定的日常价格。', '索比恩在资料中的购买力比较，是帮助理解日常消费的大致参照，并不意味着人类世界的货币可以按这一比例在帷幕交易。'],
    ['交换什么', '跨越两个世界的交换可能涉及稀有材料、魔药、造物、技术与情报。这类贸易更接近以特殊资源交换特殊资源，而不是依赖公开、统一的金融市场。', '现存记载还提到走私网络：从帷幕流出的物品可能包括药材、魔药和特殊生物，从人类世界流入的则可能包括精密设备、工业制品与信息技术产品。'],
    ['边界与风险', '帷幕使普通人难以察觉被覆盖的地域，但具有魔法能力的生命可能感知并穿越它。这种不对称，使接触外部世界的机会分布不均，也使跨界物资的流动难以等同于普通国内贸易。', '隐蔽交易的价格可能大幅波动。关于具体线路、参与者和交易规模，现有材料尚不足以绘制可靠的完整网络。']
  ]);
})();
